<script setup lang="ts">
export type FormField={key:string;label:string;type?:string;required?:boolean;options?:{id:string;name:string}[];min?:number;max?:number;step?:string;multiple?:boolean;readonly?:boolean};
defineProps<{row:Record<string,any>;fields:FormField[]}>();
const emit=defineEmits<{change:[key:string]}>();
</script>
<template><div class="proposal-fields"><label v-for="field in fields" :key="field.key"><span>{{field.label}}</span><select v-if="field.options" v-model="row[field.key]" :required="field.required" :multiple="field.multiple" @change="emit('change',field.key)"><option v-if="!field.multiple" value="">Seçiniz</option><option v-for="option in field.options" :key="option.id" :value="option.id">{{option.name}}</option></select><textarea v-else-if="field.type==='textarea'" v-model="row[field.key]" maxlength="5000"/><DateInput :range-message="field.key.startsWith('validity') ? 'Geçerlilik başlangıcı geçerlilik bitişinden büyük olamaz.' : 'İlk tarih son tarihten büyük olamaz.'" :range-start="row[({lastDate:'firstDate',validityLastDate:'validityFirstDate',checkOut:'checkIn',closedTo:'closedFrom',buggyTo:'buggyFrom'} as Record<string,string>)[field.key]]" :range-end="row[({firstDate:'lastDate',validityFirstDate:'validityLastDate',checkIn:'checkOut',closedFrom:'closedTo',buggyFrom:'buggyTo'} as Record<string,string>)[field.key]]" v-else-if="field.type === 'date'" v-model="row[field.key]" :min="field.min" :max="field.max" :required="field.required" :readonly="field.readonly" @change="emit('change',field.key)" /><input v-else v-model="row[field.key]" :type="field.type??'text'" :min="field.min" :max="field.max" :step="field.step" :required="field.required" :readonly="field.readonly" :maxlength="field.type==='text'||!field.type?200:undefined" @change="emit('change',field.key)"></label></div></template>
<style scoped>.proposal-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}label{display:flex;flex-direction:column;gap:5px;font:11px Tahoma,sans-serif;color:#31526c}input,select,textarea{width:100%;box-sizing:border-box;border:1px solid #8ab1ce;background:white;color:#154c75;padding:6px;min-height:30px;font:12px Tahoma,sans-serif}select[multiple]{height:65px}input[type=checkbox]{width:18px}textarea{min-height:60px}</style>
